import {cleanPucks,cleanPuckTransitions} from './drill-pucks.js';
import {cleanMotionPaths,cleanPuckPass} from './motion-paths.js';
import {cleanInk} from './board-ink.js';
import {OWN,MAX_TURNS,insideIce} from './trial-model.js';
export const REPLAY_LIMITS=Object.freeze({count:10,steps:MAX_TURNS,perReplay:100*1024,total:1024*1024});
const OPP=['OC','OL','OR','ODL','ODR'],ID=/^[a-z0-9]+(?:-[a-z0-9]+)*$/;
export const replayId=()=>globalThis.crypto?.randomUUID?.()||'replay-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(12)),v=>v.toString(16).padStart(2,'0')).join('');
const bytes=v=>new TextEncoder().encode(JSON.stringify(v)).length;
const coordinate=p=>{if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<40||p.x>960||p.y<50||p.y>550)throw Error('演練座標資料無效');return {x:+p.x.toFixed(3),y:+p.y.toFixed(3)};};
export function prepareReplay({title,courseTitle,caseLabel,role,history},id=replayId(),createdAt=new Date().toISOString()){
 if(!Array.isArray(history)||history.length<1||history.length>REPLAY_LIMITS.steps+1)throw Error(`每份最多 ${REPLAY_LIMITS.steps} 步`);
 const first=history[0];if(!ID.test(first.lessonId)||!ID.test(first.caseId)||typeof first.lessonId!=='string'||typeof first.caseId!=='string')throw Error('演練來源無效');
 if(![...OWN,...OPP].includes(role))throw Error('觀察位置無效');
 const blank=first.lessonId==='tactics-board';if(history.length===1&&(!blank||!first.annotations?.length&&!first.activePlayers?.length&&!first.pucks?.length))throw Error('請先走一步或畫上戰術線');
 const clean=history.map((s,i)=>{
  if(blank&&(!Array.isArray(s.activePlayers)||new Set(s.activePlayers).size!==s.activePlayers.length||s.activePlayers.some(id=>![...OWN,...OPP].includes(id))||s.owner!==null&&!s.activePlayers.includes(s.owner)))throw Error('戰術板場上球員資料無效');
  if(blank&&Array.isArray(s.pucks)){const pucks=cleanPucks(s.pucks),transitions=cleanPuckTransitions(s.puckTransitions||{},pucks),selected=pucks.find(p=>p.id===s.activePuckId);if(pucks.some(p=>!insideIce(p)||p.owner&&!s.activePlayers.includes(p.owner))||pucks.length&&!selected||!pucks.length&&s.activePuckId!==null||selected&&(s.owner!==selected.owner||Math.hypot(s.puck.x-selected.x,s.puck.y-selected.y)>.02))throw Error('多球局面無效');for(const [id,t] of Object.entries(transitions)){const ball=pucks.find(p=>p.id===id);if(t.follows&&t.follows!==ball.owner)throw Error('冰球帶球者無效');if(t.pass){const pass=t.pass,start=s.own[pass.from]||s.opponents[pass.from],end=pass.line.type==='shot'?ball:s.own[pass.to]||s.opponents[pass.to];if(i===0||ball.owner!==pass.to||!s.activePlayers.includes(pass.from)||pass.to!==null&&!s.activePlayers.includes(pass.to)||pass.line.points.some(p=>!insideIce(p))||Math.hypot(pass.line.points[0].x-start.x,pass.line.points[0].y-start.y)>.2||Math.hypot(pass.line.points.at(-1).x-end.x,pass.line.points.at(-1).y-end.y)>.2)throw Error('多球傳球路線無效');}}}
  if(blank&&s.puckOnIce===false&&s.owner!==null)throw Error('場外冰球不能指定持球者');
  if(s.turn!==i||s.lessonId!==first.lessonId||s.caseId!==first.caseId||s.baseTime!==first.baseTime||!Number.isFinite(s.baseTime)||s.baseTime<0||s.baseTime>3600||!['attack','defend'].includes(s.direction)||s.owner!==null&&![...OWN,...OPP].includes(s.owner))throw Error('演練步驟資料無效');
  if(blank){const paths=cleanMotionPaths(s.motionPaths||{});for(const [id,line] of Object.entries(paths)){if(line.points.some(p=>!insideIce(p))||i===0||!s.activePlayers.includes(id)||Math.hypot(line.points.at(-1).x-(s.own[id]||s.opponents[id]).x,line.points.at(-1).y-(s.own[id]||s.opponents[id]).y)>.2)throw Error('演練路線終點無效');const previous=history[i-1];if(previous.activePlayers.includes(id)){const start=previous.own[id]||previous.opponents[id];if(Math.hypot(line.points[0].x-start.x,line.points[0].y-start.y)>.2)throw Error('演練路線起點無效');}}if(s.puckPass){const pass=cleanPuckPass(s.puckPass),start=s.own[pass.from]||s.opponents[pass.from],end=pass.line.type==='shot'?s.puck:s.own[pass.to]||s.opponents[pass.to];if(i===0||!s.activePlayers.includes(pass.from)||pass.to!==null&&!s.activePlayers.includes(pass.to)||s.owner!==pass.to||pass.line.points.some(p=>!insideIce(p))||Math.hypot(pass.line.points[0].x-start.x,pass.line.points[0].y-start.y)>.2||Math.hypot(pass.line.points.at(-1).x-end.x,pass.line.points.at(-1).y-end.y)>.2)throw Error('傳球路線起終點無效');}if(s.puckFollows&&(!paths[s.puckFollows]||s.owner!==s.puckFollows))throw Error('帶球路線無效');}
  return {...(blank?{activePlayers:[...s.activePlayers],puckOnIce:s.puckOnIce!==false,annotations:cleanInk(s.annotations||[]),motionPaths:cleanMotionPaths(s.motionPaths||{}),puckFollows:s.puckFollows||null,puckPass:cleanPuckPass(s.puckPass),...(Array.isArray(s.pucks)?{pucks:cleanPucks(s.pucks),activePuckId:s.activePuckId,puckTransitions:cleanPuckTransitions(s.puckTransitions||{},s.pucks),moveEndsAt:s.moveEndsAt===.55?.55:0}:{})}:{}),own:Object.fromEntries(OWN.map(r=>[r,coordinate(s.own?.[r])])),opponents:Object.fromEntries(OPP.map(r=>[r,coordinate(s.opponents?.[r])])),puck:coordinate(s.puck),owner:s.owner,turn:i,baseTime:s.baseTime,direction:s.direction,lessonId:s.lessonId,caseId:s.caseId,events:Array.isArray(s.events)?s.events.slice(0,12).map(x=>String(x).slice(0,500)):[],responses:Array.isArray(s.responses)?s.responses.slice(0,10).map(x=>{if(![...OWN,...OPP].includes(x.id))throw Error('回應位置無效');return {id:x.id,from:coordinate(x.from),to:coordinate(x.to),body:String(x.body).slice(0,500)};}):[]};
 });
 const text=x=>String(x??'').trim().slice(0,80);
 const record={schemaVersion:1,id,title:text(title)||`${text(courseTitle)} · ${history.length-1} 步`,courseId:first.lessonId,caseId:first.caseId,courseTitle:text(courseTitle),caseLabel:text(caseLabel),role,createdAt,steps:clean.length-1,history:clean};
 const byteLength=bytes(record);if(byteLength>REPLAY_LIMITS.perReplay)throw Error('這份演練超過 100 KB，請減少步驟');
 const {history:_,...meta}=record;return {record,meta:{...meta,byteLength}};
}
export function checkReplayQuota(items,newMeta){
 if(items.length>=REPLAY_LIMITS.count)throw Error('已達 10 份上限，請先匯出備份並刪除舊演練');
 if(newMeta.byteLength>REPLAY_LIMITS.perReplay)throw Error('單份演練超過 100 KB');
 if(items.reduce((n,x)=>n+x.byteLength,0)+newMeta.byteLength>REPLAY_LIMITS.total)throw Error('演練資料已達 1 MB 上限，請先刪除舊演練');
}
let opening;
function db(){if(!globalThis.indexedDB)return Promise.reject(Error('此瀏覽器無法使用演練儲存'));if(!opening)opening=new Promise((resolve,reject)=>{const req=indexedDB.open('courtiq-trial-library',1);req.onupgradeneeded=()=>{req.result.createObjectStore('meta',{keyPath:'id'});req.result.createObjectStore('records',{keyPath:'id'});};req.onsuccess=()=>{req.result.onversionchange=()=>{req.result.close();opening=null;};resolve(req.result);};req.onerror=()=>reject(Error('無法開啟演練儲存空間'));req.onblocked=()=>reject(Error('請關閉其他學習室分頁後再試'));}).catch(e=>{opening=null;throw e;});return opening;}
async function read(store,id){const database=await db();return new Promise((resolve,reject)=>{const t=database.transaction(store),r=id?t.objectStore(store).get(id):t.objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('讀取演練失敗'));});}
export async function listReplays(){return (await read('meta')).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
export async function loadReplay(id){const r=await read('records',id);if(!r)throw Error('找不到這份演練');if(r.schemaVersion!==1)throw Error('不支援的演練版本');return prepareReplay(r,r.id,r.createdAt).record;}
export async function saveReplay(input){const {record,meta}=prepareReplay(input),database=await db();await new Promise((resolve,reject)=>{const t=database.transaction(['meta','records'],'readwrite');let failure;const req=t.objectStore('meta').getAll();req.onsuccess=()=>{try{checkReplayQuota(req.result,meta);t.objectStore('meta').add(meta);t.objectStore('records').add(record);}catch(e){failure=e;t.abort();}};t.oncomplete=resolve;t.onabort=()=>reject(failure||Error('儲存失敗，瀏覽器空間可能不足；現有演練不受影響'));t.onerror=()=>{};});return meta;}
export async function deleteReplay(id){const database=await db();await new Promise((resolve,reject)=>{const t=database.transaction(['meta','records'],'readwrite');t.objectStore('meta').delete(id);t.objectStore('records').delete(id);t.oncomplete=resolve;t.onabort=()=>reject(Error('刪除演練失敗'));});}
